342: function petshop_xml_block_zb_create( $continue_import, $data, $import_id ) {
343: 
344:     // Saugiklis: tik ZB importas #2
345:     if ( ! in_array( (int) $import_id, PETSHOP_XML_ZB_IMPORT_IDS, true ) ) {
346:         return $continue_import;
347:     }
348:     // Saugiklis: $data turi buti masyvas
349:     if ( ! is_array( $data ) ) {
350:         return $continue_import;
351:     }
352: 
353:     $name     = petshop_xml_tekstas( $data['name'] ?? '' );
354:     $category = petshop_xml_tekstas( $data['category'] ?? '' ); // S1691: masyvas → tekstas
355:     $brand    = petshop_xml_tekstas( $data['brand'] ?? '' );
356:     $price    = isset( $data['price'] ) ? (float) str_replace( ',', '.', (string) $data['price'] ) : 0.0;
357:     $qty      = isset( $data['qty'] )   ? (int) $data['qty'] : 0;
358: 
359:     // Fail-safe: jei tuscia esmine info -> leisti (neblokuojam aklai)
360:     if ( $name === '' && $category === '' ) {
361:         return $continue_import;
362:     }
363: 
364:     // v1.5.17: EXCLUDED BRAND -> NEKURTI (prie vartu).
365:     //
366:     //   Tokie brandai (Hau&Miau, Bioveterinary ir kt.) pas mus JAU egzistuoja
367:     //   kaip Legacy prekes (su istorija, kaina, SEO). ZB juos irgi siuncia, bet
368:     //   jie NETURI patekti is ZB — turi but blokuojami "prie vartu", o ne
369:     //   sukuriami ir tik po to metami i draft (excluded_brand). Anksciau
370:     //   is_excluded_brand() veike tik PO sukurimo (initial_import) -> preke buvo
371:     //   sukuriama, parsisiusta nuotrauka, tik po to draft -> siuksles + kreditai.
372:     //   Dabar blokuojam PRIES sukurima (kaip konservas/qty/aksesuaras patikros).
373:     //
374:     //   Brandas tikrinamas is $data['brand']; jei tuscias -> is name (fallback),
375:     //   nes is_excluded_brand() moka atpazinti pagal pavadinima.
376:     if ( class_exists( 'Petshop_Import_Rules' ) ) {
377:         $rules_gate   = new Petshop_Import_Rules();
378:         $brand_check  = $brand !== '' ? $brand : $name;
379:         $brand_check  = trim( html_entity_decode( $brand_check, ENT_QUOTES | ENT_HTML5, 'UTF-8' ) );
380:         if ( $brand_check !== '' && $rules_gate->is_excluded_brand( $brand_check ) ) {
381:             petshop_xml_log_structured( [
382:                 'action'    => 'ZB-BLOCK-CREATE',
383:                 'name'      => mb_substr( $name, 0, 60 ),
384:                 'brand'     => mb_substr( $brand_check, 0, 40 ),
385:                 'reason'    => 'excluded_brand',
386:                 'import_id' => $import_id,
387:                 'note'      => 'ZB create prevented (excluded brand, exists as Legacy) at the gate (v1.5.17)',
388:             ] );
389:             return false; // BLOKUOTI kurima
390:         }
391:     }
392: 
393:     // Konservas -> LEISTI (taps draft per initial_import, box rinkiniams)
394:     if ( petshop_xml_text_is_konservas( $category, $name ) ) {
395:         return $continue_import;
396:     }
397: 
398:     // v1.5.15: NAUJA preke qty <= 0 -> NEKURTI.
399:     //
400:     //   Priezastis (savininko sprendimas 2026-06-14): nauja preke be likucio
401:     //   neturi SEO istorijos ir nera paklausos (niekas jos nemate). Jos kurti
402:     //   neverta — tik kauptu siuksles. Jei ZB veliau atsius ja SU likuciu
403:     //   (qty>0), ji bus sukurta tada (publish). Tai automatinis "blokavimas":
404:     //   nauja qty=0 nekuriama, bet grizus su likuciu — kuriama.
405:     //
406:     //   ESAMOS prekes qty=0 tvarkomos initial_import() (buvusi publish ->
407:     //   lieka matoma SEO+paklausai; gimusi draft -> 30 d. cleanup).
408:     if ( $qty <= 0 ) {
409:         petshop_xml_log_structured( [
410:             'action'    => 'ZB-BLOCK-CREATE',
411:             'name'      => mb_substr( $name, 0, 60 ),
412:             'category'  => mb_substr( $category, 0, 60 ),
413:             'price'     => $price,
414:             'qty'       => $qty,
415:             'reason'    => 'qty_zero_new_no_history',
416:             'import_id' => $import_id,
417:             'note'      => 'ZB create prevented (new qty=0, no SEO/demand) before image download (v1.5.15)',
418:         ] );
419:         return false; // BLOKUOTI kurima
420:     }
421: 
422:     // Aksesuaras: pigus (< kartele) IR NE konservas IR turi likuti -> NEKURTI
423:     if ( $price > 0 && $price < PETSHOP_XML_ZB_MIN_COST ) {
424:         petshop_xml_log_structured( [
425:             'action'    => 'ZB-BLOCK-CREATE',
426:             'name'      => mb_substr( $name, 0, 60 ),
427:             'category'  => mb_substr( $category, 0, 60 ),
428:             'price'     => $price,
429:             'qty'       => $qty,
430:             'reason'    => 'cost_below_minimum_accessory',
431:             'import_id' => $import_id,
432:             'note'      => 'ZB create prevented (accessory below min cost) before image download (v1.5.13)',
433:         ] );
434:         return false; // BLOKUOTI kurima
435:     }
436: 
437:     // Praeina -> leisti kurti normaliai
438:     return $continue_import;
439: }
