461: function petshop_xml_block_zb_cheap_update( $continue_import, $post_id, $data, $import_id ) {
462: 
463:     if ( get_post_type( $post_id ) !== 'product' ) {
464:         return $continue_import;
465:     }
466: 
467:     // Tik ZB importai (#2 initial, #3 stock)
468:     if ( ! in_array( (int) $import_id, PETSHOP_XML_ZB_ALL_IMPORT_IDS, true ) ) {
469:         return $continue_import;
470:     }
471: 
472:     // Legacy prekes — jau blokuotos block_legacy_update (prioritetas 9). Saugiklis.
473:     if ( petshop_xml_is_legacy_product( $post_id ) ) {
474:         return $continue_import;
475:     }
476: 
477:     // Manual override — neliesti
478:     if ( get_post_meta( $post_id, '_manual_price_override', true ) === 'yes' ) {
479:         return $continue_import;
480:     }
481: 
482:     $zb_cost = (float) get_post_meta( $post_id, '_zb_cost', true );
483: 
484:     // Fail-safe: jei savikainos nezinom -> leisti (neblokuojam aklai)
485:     if ( $zb_cost <= 0 ) {
486:         return $continue_import;
487:     }
488: 
489:     // Konservas -> NEBLOKUOJAM (konservai leidziami net pigus, box rinkiniai)
490:     if ( petshop_xml_is_konservas( $post_id ) ) {
491:         return $continue_import;
492:     }
493: 
494:     // Pigi (< kartele) IR ne konservas IR esama -> BLOKUOTI update
495:     if ( $zb_cost < PETSHOP_XML_ZB_MIN_COST ) {
496:         petshop_xml_log_structured( [
497:             'action'    => 'ZB-BLOCK-CHEAP-UPDATE',
498:             'post_id'   => $post_id,
499:             'sku'       => (string) get_post_meta( $post_id, '_sku', true ),
500:             'zb_cost'   => $zb_cost,
501:             'import_id' => $import_id,
502:             'note'      => 'ZB update prevented for existing cheap non-konservas (no image reload, v1.5.14)',
503:         ] );
504:         return false;
505:     }
506: 
507:     return $continue_import;
508: }
